    ': ' + esc(x.lead.nombre) + '</b>\n' + esc(x.lead.web) + '\n\n' + esc(resumen) +
    '\n\n<i>Respondió (está en contacto@):</i>\n' + esc(x.texto.slice(0, 700)) +
